const customCourseLessons: Record<string, Lesson[]> = {
  "Python Programming": [
    { title: "1. Run Python and understand statements", duration: "10 min", content: "## Learning goals\nRun a Python script and distinguish values, expressions, and statements.\n\n## Example\n```python\nname = \"Ada\"\nprint(f\"Hello, {name}!\")\n```\nThe assignment stores a string in `name`; the f-string inserts its value into the message. Python executes statements in order.\n\n## Practice\nChange the name, print a second message, and predict the output before running it.\n\n## Check yourself\nExplain the difference between `name` and the string `\"name\"`.\n\nSource: Python official tutorial, https://docs.python.org/3/tutorial/" },
    { title: "2. Variables, types, and input", duration: "12 min", content: "## Core idea\nVariables refer to values. Common built-in types include `str`, `int`, `float`, and `bool`. Input from `input()` is text, so convert it before arithmetic.\n\n## Worked example\n```python\nage_text = input(\"Age: \")\nage = int(age_text)\nprint(age + 1)\n```\nIf the user types `18`, the program prints `19`. If they type words, `int()` raises `ValueError`.\n\n## Practice\nAsk for two numbers and print their sum. Add a `try/except ValueError` to handle invalid input.\n\n## Common mistake\nAdding two strings joins them: `\"2\" + \"3\"` is `\"23\"`, not `5`.\n\nSource: https://docs.python.org/3/tutorial/" },
    { title: "3. Decisions with if, elif, and else", duration: "12 min", content: "## Core idea\nConditions evaluate to `True` or `False`. Python uses indentation to define each block. Use `==` to compare values and `=` to assign them.\n\n## Worked example\n```python\nscore = 72\nif score >= 80:\n    grade = \"A\"\nelif score >= 60:\n    grade = \"B\"\nelse:\n    grade = \"C\"\nprint(grade)  # B\n```\nOrder matters: the first matching branch runs.\n\n## Practice\nWrite a temperature classifier with at least three ranges. Test values on each boundary, such as 0 and 1.\n\n## Check yourself\nWhy might checking a broad condition before a narrow condition cause a bug?\n\nSource: https://docs.python.org/3/tutorial/" },
    { title: "4. Loops and collections", duration: "15 min", content: "## Core idea\nA `for` loop visits items in an iterable; a `while` loop repeats while its condition stays true. Lists preserve order and can hold multiple values.\n\n## Worked example\n```python\nprices = [10, 15, 5]\ntotal = 0\nfor price in prices:\n    total += price\nprint(total)  # 30\n```\nThe accumulator starts at zero and adds each price once.\n\n## Practice\nFind the largest number in a list without using `max()`. Test an empty list and decide how your code should handle it.\n\n## Common mistakes\nInfinite `while` loops, off-by-one ranges, and modifying a list while iterating over it.\n\nSource: https://docs.python.org/3/tutorial/" },
    { title: "5. Functions, errors, and testing", duration: "18 min", content: "## Core idea\nFunctions package reusable behavior. Parameters are inputs; `return` sends a result to the caller. Handle expected invalid input and test normal plus boundary cases.\n\n## Worked example\n```python\ndef discount(price, rate):\n    if price < 0 or not 0 <= rate <= 1:\n        raise ValueError(\"Invalid price or rate\")\n    return price * (1 - rate)\n\nassert discount(100, 0.2) == 80\n```\nThe assertion checks an expected result; it does not prove every case works.\n\n## Practice\nWrite a function that converts Celsius to Fahrenheit. Test freezing point, room temperature, and a negative temperature.\n\n## Further reading\nPython tutorial and library documentation: https://docs.python.org/3/tutorial/ and https://docs.python.org/3/library/unittest.html" },
  ],
  "Web Development 101": [
    { title: "1. How a web page reaches the browser", duration: "10 min", content: "## The request-response cycle\nA browser requests a URL; a server or CDN responds with HTML, CSS, JavaScript, images, and other resources. HTML describes structure, CSS styles it, and JavaScript adds behavior.\n\n## Example\n```html\n<h1>Welcome</h1>\n<p>This is my first page.</p>\n```\nThe browser parses the HTML and builds a document tree. A page can work without JavaScript, so start with semantic HTML.\n\n## Practice\nCreate a page with a title, a main heading, two paragraphs, and a link. Check that the link has a meaningful destination.\n\nFurther reading: MDN Getting started, https://developer.mozilla.org/en-US/docs/Learn" },
    { title: "2. Semantic HTML and accessible forms", duration: "12 min", content: "## Core idea\nUse elements for their meaning: `<main>`, `<nav>`, `<article>`, headings in logical order, and explicit form labels. Semantic structure helps assistive technology, search engines, and maintainers.\n\n## Example\n```html\n<label for=\"email\">Email address</label>\n<input id=\"email\" name=\"email\" type=\"email\" required>\n<button type=\"submit\">Join</button>\n```\nA visible label tells users what the field expects; the browser can validate the email format, but the server must still validate submitted data.\n\n## Practice\nBuild a contact form with labels, required fields, and helpful error text. Navigate it using only the keyboard.\n\nFurther reading: https://developer.mozilla.org/en-US/docs/Learn/Accessibility" },
    { title: "3. CSS layout with Flexbox and Grid", duration: "15 min", content: "## Core idea\nUse Flexbox for arranging items along one main axis and Grid for two-dimensional rows and columns. Prefer responsive constraints over fixed widths that break on small screens.\n\n## Example\n```css\n.cards {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\n  gap: 1rem;\n}\n```\nThe browser fits as many columns as can satisfy the minimum width, then wraps the rest.\n\n## Practice\nCreate three cards and test at a narrow phone width and a wide desktop width. Check overflow and text readability.\n\nFurther reading: https://developer.mozilla.org/en-US/docs/Learn/CSS" },
    { title: "4. JavaScript events and DOM updates", duration: "15 min", content: "## Core idea\nJavaScript responds to events such as clicks and form submissions. Query elements deliberately, validate input, and update the DOM without injecting untrusted strings as HTML.\n\n## Example\n```html\n<button id=\"counter\">Add one</button>\n<p id=\"value\">0</p>\n<script>\nlet count = 0;\ndocument.querySelector('#counter').addEventListener('click', () => {\n  count += 1;\n  document.querySelector('#value').textContent = String(count);\n});\n</script>\n```\nUsing `textContent` treats the value as text instead of parsing it as HTML.\n\n## Practice\nBuild a counter with increment and reset controls. Ensure each button has a clear accessible name.\n\nFurther reading: https://developer.mozilla.org/en-US/docs/Web/JavaScript" },
    { title: "5. Fetch data, handle errors, and deploy", duration: "18 min", content: "## Core idea\nA frontend request can fail because of network issues, authorization, server errors, or invalid data. Check HTTP status, show a loading state, and provide a useful error state. Never expose private API keys in browser code.\n\n## Example\n```js\nasync function loadUsers() {\n  const response = await fetch('/api/users');\n  if (!response.ok) throw new Error('Could not load users');\n  return response.json();\n}\n```\nProduction code should catch the error at the UI boundary and show a retry option.\n\n## Practice\nConnect a page to a public test API; show loading, success, empty, and failure states. Then deploy and test the deployed URL on mobile.\n\nFurther reading: https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API" },
  ],
  "Algebra Basics": [
    { title: "1. Variables and expressions", duration: "10 min", content: "## Core idea\nA variable represents a value. An expression combines values and operations; an equation states that two expressions are equal.\n\n## Worked example\nFor 3x + 2, if x = 4 then 3(4) + 2 = 14. Multiplication happens before addition unless parentheses change the order.\n\n## Practice\nEvaluate 5a - 7 when a = 3. Then write an expression for twice a number plus nine.\n\n## Common mistake\n3x means 3 multiplied by x, not the two-digit number thirty-something.\n\nFurther reading: OpenStax Algebra and Trigonometry, https://openstax.org/details/books/algebra-and-trigonometry" },
    { title: "2. Solve linear equations", duration: "12 min", content: "## Goal\nKeep an equation balanced: apply the same operation to both sides.\n\n## Worked example\nSolve 4x - 5 = 19. Add 5 to both sides: 4x = 24. Divide both sides by 4: x = 6. Check: 4(6) - 5 = 19.\n\n## Practice\nSolve 3x + 7 = 22 and 5 - 2x = 13. Substitute each answer into its original equation.\n\n## Common mistake\nMoving a term across the equals sign without changing the operation is not a valid algebra step.\n\nSource: https://openstax.org/details/books/elementary-algebra-2e" },
    { title: "3. Inequalities and number lines", duration: "12 min", content: "## Core idea\nAn inequality describes a range of values. Add or subtract the same number on both sides without changing its direction. When multiplying or dividing by a negative number, reverse the inequality sign.\n\n## Worked example\n-2x > 6. Divide by -2 and reverse the sign: x < -3.\n\n## Practice\nSolve 2x + 1 <= 9 and -3x >= 12. Sketch each solution on a number line.\n\n## Check yourself\nExplain why dividing by a negative reverses the sign.\n\nFurther reading: https://openstax.org/details/books/elementary-algebra-2e" },
    { title: "4. Functions and input-output tables", duration: "15 min", content: "## Core idea\nA function maps each allowed input to exactly one output. In f(x) = 2x + 1, substitute the input for every x. The domain is the set of allowed inputs; the range is the set of outputs.\n\n## Worked example\nf(3) = 2(3) + 1 = 7. If the input is -2, f(-2) = -3.\n\n## Practice\nFor g(x) = x^2 - 4, calculate g(0), g(2), and g(-2). Explain why two inputs can produce the same output.\n\n## Common mistake\nf(3) means the output at input 3, not f multiplied by 3.\n\nFurther reading: https://openstax.org/details/books/algebra-and-trigonometry" },
    { title: "5. Systems of linear equations", duration: "18 min", content: "## Core idea\nA system asks for values that satisfy multiple equations simultaneously. Substitution solves one equation for a variable and inserts it into the other.\n\n## Worked example\ny = x + 1 and x + y = 7. Substitute: x + (x + 1) = 7, so 2x = 6, x = 3, and y = 4. Both equations are satisfied.\n\n## Practice\nSolve y = 2x and x + y = 12. Verify the answer in both equations.\n\n## Interpret results\nTwo lines can intersect once, be parallel with no solution, or describe the same line with infinitely many solutions.\n\nFurther reading: https://openstax.org/details/books/elementary-algebra-2e" }
  ],
  "Network Security": [
    { title: "1. Assets, threats, and the CIA triad", duration: "10 min", content: "## Core idea\nIdentify what must be protected: accounts, devices, services, and data. The CIA triad means confidentiality (only authorized access), integrity (data remains accurate), and availability (systems remain usable).\n\n## Worked example\nFor a student portal, MFA and least privilege help confidentiality; audit logs and change controls support integrity; backups and redundancy support availability. One control rarely solves every risk.\n\n## Practice\nList three assets in a small business network and assign one likely threat and one control to each.\n\nFurther reading: NIST Cybersecurity Framework, https://www.nist.gov/cyberframework" },
    { title: "2. Network segmentation and least privilege", duration: "12 min", content: "## Core idea\nSegmentation divides a network into zones so compromise in one area does not automatically expose everything else. Least privilege grants only the access needed for a role.\n\n## Worked example\nSeparate guest Wi-Fi, staff devices, payment systems, and administration. Guest devices should not initiate connections to the payment network. Document permitted flows before implementing rules.\n\n## Practice\nDraw four zones for a school or shop network. Mark which zones need to communicate and why.\n\nFurther reading: https://www.cisa.gov/resources-tools/resources/zero-trust-maturity-model" },
    { title: "3. Firewalls and rule evaluation", duration: "12 min", content: "## Core idea\nA firewall applies rules to traffic attributes such as source, destination, protocol, and port. Rule order and the default policy matter. Deny-by-default reduces unintended access, but rules must still permit required services.\n\n## Worked example\nA web server may accept HTTPS from clients while management access is limited to an administrator network. Do not expose remote administration to every source address.\n\n## Practice\nList allowed inbound services for a fictional web server, intended sources, business reason, and owner.\n\nFurther reading: NIST firewall guidance, https://csrc.nist.gov/publications/detail/sp/800-41/rev-1/final" },
    { title: "4. Monitoring logs and responding to alerts", duration: "15 min", content: "## Core idea\nLogs provide evidence about authentication, network connections, policy changes, and system errors. Useful alerts have context, severity, an owner, and a documented response. A single failed login is not proof of compromise.\n\n## Worked example\nRepeated failed logins followed by a successful login from an unusual location warrants checking MFA status, session activity, and related alerts before drawing a conclusion. Preserve relevant logs.\n\n## Practice\nWrite an incident note with time, affected asset, observed evidence, confidence, containment step, and next verification action.\n\nFurther reading: https://www.cisa.gov/resources-tools/resources/logging-made-easy" },
    { title: "5. Incident containment and recovery", duration: "18 min", content: "## Core idea\nA response sequence is prepare, detect and analyze, contain, eradicate, recover, and learn. Choose containment that limits harm while preserving evidence and business needs. Confirm recovery by validating controls, not just restarting a service.\n\n## Worked example\nFor a suspected compromised staff laptop, follow the response plan to isolate it, notify the responsible lead, preserve logs, rotate affected credentials from a trusted device, and reimage only after evidence and approvals are considered.\n\n## Practice\nCreate a response checklist for a compromised email account. Include containment, evidence, recovery, and user communication.\n\nFurther reading: NIST incident handling guidance, https://csrc.nist.gov/pubs/sp/800/61/r2/final" }
  ]
};

function generateLessons(courseTitle: string, categoryId: string): Lesson[] {
  if (customCourseLessons[courseTitle]) return customCourseLessons[courseTitle];
  const topics = lessonTopicsByCategory[categoryId] || [];
  const durations = ['5 min', '8 min', '10 min', '12 min', '15 min', '18 min', '20 min'];
  
  return topics.map((topic, i) => ({
    title: `${topic}`,
    content: generateLessonContent(courseTitle, topic, i, categoryId),
    duration: durations[i % durations.length],
  }));
}

function generateLessonContent(courseTitle: string, topic: string, index: number, categoryId: string): string {
  const common = "## Learning goals\n\nBy the end of this lesson, explain " + topic + ", work through an example, and identify one limitation.\n\n## Core idea\n\n" + topic + " is part of " + courseTitle + ". Define key terms precisely, connect the idea to a concrete problem, and write down what evidence could change your conclusion.";

  const teaching: Record<string, string> = {
    technology: "## Worked example\n\nFor a programming topic, reduce the problem to a small reproducible example. Example in TypeScript:\n\nfunction addTax(price: number, rate: number): number { return price * (1 + rate); }\naddTax(100, 0.15) returns 115.\n\nTrace each input, the expression, and the output. Test normal values, edge cases, and invalid input.\n\n## Practice\n\nWrite a small example related to " + topic + ". Test one normal case, one edge case, and one invalid input. Explain what each test proves.\n\n## Common mistakes\n\n- Copying code without understanding inputs and outputs\n- Ignoring validation, errors, or security\n- Assuming one passing example proves correctness",
    mathematics: "## Worked example\n\nSolve 2x + 3 = 11. Subtract 3 from both sides: 2x = 8. Divide by 2: x = 4. Check by substitution: 2(4) + 3 = 11.\n\nThe check catches mistakes instead of relying on intuition.\n\n## Practice\n\nCreate a problem using " + topic + ", solve it line by line, then substitute your answer back into the original statement. State any assumptions.\n\n## Common mistakes\n\n- Skipping intermediate steps\n- Applying a rule without checking its conditions\n- Forgetting units, domains, or restrictions",
    science: "## How to investigate the idea\n\nSeparate observation from explanation. State a question, propose a testable hypothesis, identify independent and dependent variables, and record results with units. Change one variable at a time where possible and note sources of error.\n\n## Worked example\n\nQuestion: does changing light exposure affect plant growth? Keep plant type, soil, water, and container consistent; vary light exposure; measure height at the same time daily. The result supports a hypothesis only to the extent that the design rules out other explanations.\n\n## Practice\n\nDesign a safe investigation related to " + topic + ". State the hypothesis, variables, measurement method, and one limitation.\n\n## Common mistakes\n\n- Treating correlation as proof of causation\n- Ignoring measurement uncertainty or sample size\n- Making a conclusion stronger than the evidence supports",
    economics: "## Worked example\n\nOpportunity cost is the value of the next-best alternative you give up. If you have two hours and could earn $10 per hour, choosing to study means giving up up to $20 in possible earnings. The calculation changes when the alternatives have different benefits or constraints.\n\nFor " + topic + ", distinguish assumptions from observations, ask who benefits, who bears the cost, and what changes when conditions change.\n\n## Practice\n\nChoose a real market or household decision. Identify the scarce resource, alternatives, trade-off, and one useful piece of data.\n\n## Common mistakes\n\n- Confusing nominal values with inflation-adjusted values\n- Treating assumptions as universal facts\n- Making causal claims from simple correlation",
    "cyber-security": "## Defensive workflow\n\nIdentify the asset, assess the threat, reduce exposure, monitor signals, and document recovery. Record the system scope, weakness, likely impact, evidence, and remediation. Only test systems you own or have explicit written authorization to assess.\n\n## Worked example\n\nFor a fictional student portal, check whether multi-factor authentication is available, login attempts are rate-limited, and alerts detect unusual sign-ins. Validate fixes in a controlled test.\n\n## Practice\n\nCreate a threat model for a fictional portal: list three assets, two threats, one control per threat, and how you would verify each control.\n\n## Common mistakes\n\n- Testing systems without authorization\n- Confusing a scan with proof of exploitability\n- Writing findings without actionable remediation",
    "ethical-hacking": "## Authorized lab workflow\n\nEthical testing starts with written permission and a defined scope. Use a local training lab or intentionally vulnerable practice environment. Document objectives, safe steps, evidence, impact, and remediation; stop if a test risks affecting real users or data.\n\n## Worked example\n\nFor a fictional login page, map expected behavior and permissions first. Test input validation with harmless lab values, record unexpected responses, and recommend parameterized queries or strict validation when appropriate. Never test a third-party system without explicit authorization.\n\n## Practice\n\nWrite a test plan for a local demo application: scope, allowed actions, out-of-scope systems, evidence, stop conditions, and report format.",
    "ai-ml": "## Worked example\n\nA machine-learning workflow defines the target, collects representative data, separates training and test data, fits a baseline, measures performance, and checks failure cases. Keep the test set separate until final evaluation; repeatedly tuning against it leaks evaluation information.\n\nFor " + topic + ", compare a simple baseline with a more complex method and explain which metric matters for the task.\n\n## Practice\n\nChoose a fictional prediction task. Define input, target, possible data leakage, a baseline, and one metric. Explain the consequences of false positives and false negatives.\n\n## Common mistakes\n\n- Evaluating only on training data\n- Ignoring class imbalance or data leakage\n- Treating a score as proof of fairness or reliability",
    history: "## Read evidence, not just summaries\n\nBuild a timeline, identify people and institutions, and distinguish primary sources from later interpretations. Ask who created a source, when, for what audience, and what perspective may be missing. Historical explanations often have multiple causes.\n\n## Practice\n\nFor " + topic + ", write a three-point timeline, name a primary source you would seek, and explain one limitation in the evidence available to you.\n\n## Common mistakes\n\n- Judging the past without considering context\n- Treating one source as a complete account\n- Confusing chronological sequence with proof of causation",
    languages: "## Practice in context\n\nLearn " + topic + " through short, meaningful phrases rather than isolated lists. Read a phrase aloud, identify the subject and verb, then change one detail to make a new sentence. Revisit it later to strengthen recall.\n\n## Practice\n\nCreate five short sentences using the key pattern. Say them aloud, translate them back without looking, and mark words or grammar you had to guess. Check pronunciation with a reputable dictionary or native audio source.\n\n## Common mistakes\n\n- Memorizing translations without learning usage\n- Ignoring pronunciation and word order\n- Assuming literal translation always sounds natural",
    business: "## Worked example\n\nTurn a business idea into a testable hypothesis: a specific customer group has a problem and will pay a certain amount for a solution. Interview potential customers, observe current alternatives, and run a low-cost test before investing heavily. Record actual behavior, not only stated interest.\n\n## Practice\n\nFor " + topic + ", define the target customer, problem, value proposition, success metric, and cheapest experiment that could disprove your assumption.\n\n## Common mistakes\n\n- Treating compliments as proof of willingness to pay\n- Ignoring costs, cash flow, and customer acquisition\n- Scaling before validating demand",
    trading: "## Risk-first example\n\nBefore a hypothetical trade, define the maximum acceptable loss, position size, entry rationale, exit conditions, and what invalidates the idea. A stop order may not execute at its exact stop price in a fast or illiquid market. Past performance does not guarantee future returns.\n\n## Practice\n\nUse paper trading only. Record a hypothetical entry, invalidation point, maximum planned loss, and rationale. Review the result against the plan rather than judging only profit or loss.\n\n## Common mistakes\n\n- Risking money you cannot afford to lose\n- Treating a chart pattern as a reliable prediction\n- Ignoring fees, slippage, leverage, and emotions"
  };

  const categoryLesson = teaching[categoryId] || ("## Apply the concept\n\nUse a real or fictional scenario related to " + topic + ". Describe the situation, identify the key concept, explain your reasoning, and state what additional information could change your conclusion. For health, law, finance, or psychology, treat this as general education rather than individualized professional advice.\n\n## Practice\n\n1. Explain " + topic + " in your own words.\n2. Give one realistic example and one counterexample.\n3. List two questions you would check in a trusted textbook, official source, or peer-reviewed reference.\n4. Teach the idea to someone else and ask which step was unclear.\n\n## Common mistakes\n\n- Memorizing a definition without applying it\n- Ignoring exceptions, uncertainty, or context\n- Treating general educational content as professional advice");

  const source = categoryId === "technology" ? "Further reading: MDN Web Docs (developer.mozilla.org) or official documentation for the language/framework."
    : categoryId === "mathematics" || categoryId === "science" ? "Further reading: OpenStax free textbooks (openstax.org) and Khan Academy practice material (khanacademy.org)."
    : categoryId === "cyber-security" || categoryId === "ethical-hacking" ? "Further reading: NIST Cybersecurity Framework (nist.gov/cyberframework) and OWASP guidance (owasp.org). Practice only in authorized labs."
    : categoryId === "ai-ml" ? "Further reading: Google Machine Learning Crash Course (developers.google.com/machine-learning/crash-course) and official library documentation."
    : categoryId === "economics" ? "Further reading: World Bank Open Data (data.worldbank.org) and IMF Data (imf.org/en/Data). Check dates and country context."
    : "Source note: this is a learning scaffold. Verify important facts against a reputable textbook, official source, or peer-reviewed reference.";

  return common + "\n\n" + categoryLesson + "\n\n## Check your understanding\n\nWithout looking back, explain the key idea in two sentences. Then name one limitation, exception, or real-world factor that could change how it applies.\n\n## Source and quality note\n\n" + source + "\n\nThis is educational material, not an accredited course or professional qualification. Lesson template " + (index + 1) + " should be supplemented with verified, topic-specific examples and sources before high-stakes use.";
}

