function isValidQuestion(question: Question): boolean {
  return Boolean(
    question.question.trim() &&
    question.explanation.trim() &&
    Array.isArray(question.options) &&
    question.options.length === 4 &&
    question.options.every(option => typeof option === 'string' && option.trim()) &&
    new Set(question.options.map(option => option.trim().toLowerCase())).size === question.options.length &&
    Number.isInteger(question.correctIndex) &&
    question.correctIndex >= 0 &&
    question.correctIndex < question.options.length
  );
}

function generateQuestions(courseTitle: string, categoryId: string): Question[] {
  const categoryQs = (questionBankByCategory[categoryId] || []).filter(isValidQuestion);
  // Difficulty is only assigned when a course has a deliberately authored, leveled bank.
  // Category-level fallback questions remain ungraded by difficulty instead of receiving arbitrary labels.
  const curated = courseQuestionBanks[courseTitle];
  return (curated || categoryQs).filter(isValidQuestion);
}

function generateCourseId(title: string): string {
  return title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
}

const difficulties: Course['difficulty'][] = ['Beginner', 'Intermediate', 'Advanced'];

export const courses: Course[] = Object.entries(allCoursesByCategory).flatMap(([categoryId, titles]) =>
  titles.map((title, i) => {
    const lessons = generateLessons(title, categoryId);
    const questions = generateQuestions(title, categoryId);
    return {
      id: generateCourseId(title),
      title,
      categoryId,
      description: `A self-paced introduction to ${title} with ${lessons.length} guided lessons and ${questions.length} subject-bank practice questions. Use examples, check your understanding, and verify important facts with the suggested sources.`,
      difficulty: difficulties[i % 3],
      lessonsCount: lessons.length,
      questionsCount: questions.length,
      lessons,
      questions,
    };
  })
);

export function getCoursesByCategory(categoryId: string): Course[] {
  return courses.filter(c => c.categoryId === categoryId);
}

export function getCourseById(id: string): Course | undefined {
  return courses.find(c => c.id === id);
}

export function searchCourses(query: string): Course[] {
  const q = query.toLowerCase();
  return courses.filter(c =>
    c.title.toLowerCase().includes(q) ||
    c.categoryId.includes(q) ||
    c.description.toLowerCase().includes(q)
  );
}
